import numpy as np

def fibonacci(n):
    if n <= 0:
        return 0 if n == 0 else None
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

# Target size is 17. We construct the set S based on index selection.
# I = {0, 2, 3, 5, 7, 9, 11, 13, 15, 17, 20, 25, 30, 40, 60, 100, 125}
indices = [0, 2, 3, 5, 7, 9, 11, 13, 15, 17, 20, 25, 30, 40, 60, 100, 125]

# Construct the set S
S = [fibonacci(i) for i in indices]
S.sort()

# Generate all distinct positive differences D = {x - y | x, y in S, x > y}
differences = set()
for i in range(len(S)):
    for j in range(i):
        differences.add(S[i] - S[j])

# Check coverage for F_k up to F_40
k_max_check = 40
required_fibs = set()
for k in range(2, k_max_check + 1):
    required_fibs.add(fibonacci(k))

# Check which required Fibonacci numbers are covered
covered_fibs = []
for f_k in required_fibs:
    if f_k in differences:
        covered_fibs.append(f_k)
    else:
        # We need to know which specific F_k is missing for a detailed report
        pass

# Count how many are covered
covered_count = len(covered_fibs)
total_count = len(required_fibs)

print(f"Set S constructed successfully. Size: {len(S)}")
print(f"Total required Fibonacci differences (F_2 to F_{k_max_check}): {total_count}")
print(f"Number of covered differences up to F_{k_max_check}: {covered_count}")

# For a deeper check, print some missing ones if any are missing
if covered_count < total_count:
    print("\n--- First 5 missing Fibonacci numbers (if any) ---")
    missing = required_fibs - differences
    # Iterate and print the indices of the first 5 missing F_k
    for k in range(2, k_max_check + 1):
        f_k = fibonacci(k)
        if f_k in missing:
            print(f"F_{k} = {f_k} is missing.")
            if len(missing) >= 5:
                break

